app.get("orders", ":id") { req async throws -> View in
    guard let id = req.parameters.get("id", as: Int.self) else {
        throw Abort(.badRequest)                     // error view handled centrally
    }
    let order = try await req.db.find(Order.self, id)   // worker services the request
    return try await req.view.render("orders/show", ["order": order])  // Leaf render
}
